#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long weight;
    int index;
} Item;

static int compare_items(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;

    if (x->weight < y->weight) return 1;
    if (x->weight > y->weight) return -1;
    return 0;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    long long *a = malloc((size_t)n * sizeof(long long));
    long long *b = malloc((size_t)n * sizeof(long long));
    int *rank = malloc((size_t)n * sizeof(int));
    Item *items = malloc((size_t)n * sizeof(Item));
    long long *prefix = malloc(((size_t)n + 1) * sizeof(long long));

    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < n; i++) scanf("%lld", &b[i]);

    long long good_sum = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] >= b[i]) {
            good_sum += a[i] - b[i];
            items[i].weight = b[i];
        } else {
            items[i].weight = a[i];
        }
        items[i].index = i;
    }

    qsort(items, (size_t)n, sizeof(Item), compare_items);

    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        rank[items[i].index] = i + 1;
        prefix[i + 1] = prefix[i] + items[i].weight;
    }

    int limit = k;
    if (limit > n - 1) limit = n - 1;

    long long answer = 0;
    for (int i = 0; i < n; i++) {
        long long base = good_sum;
        if (a[i] >= b[i]) base -= a[i] - b[i];

        long long best_upgrades = 0;
        if (limit > 0) {
            if (rank[i] <= limit) {
                best_upgrades = prefix[limit + 1] - items[rank[i] - 1].weight;
            } else {
                best_upgrades = prefix[limit];
            }
        }

        long long candidate = base + best_upgrades + a[i];
        if (candidate > answer) answer = candidate;
    }

    printf("%lld\n", answer);

    free(a);
    free(b);
    free(rank);
    free(items);
    free(prefix);
    return 0;
}
